PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE videos (
	id INTEGER NOT NULL, 
	path VARCHAR(500) NOT NULL, 
	title VARCHAR(200), 
	description TEXT, 
	cover_path VARCHAR(500), 
	tags VARCHAR(500), 
	created_at DATETIME, remark TEXT, source_url VARCHAR(1000), source_platform VARCHAR(50), source_vid VARCHAR(200), video_url TEXT, cover_url TEXT, raw_data TEXT, published_at DATETIME, category VARCHAR(50) DEFAULT '', like_count INTEGER DEFAULT 0, collect_count INTEGER DEFAULT 0, comment_count INTEGER DEFAULT 0, deleted BOOLEAN DEFAULT 0, claw_status VARCHAR(20) DEFAULT 'done', claw_error TEXT, downloaded_at DATETIME, review_status VARCHAR(20) DEFAULT 'approved', 
	PRIMARY KEY (id)
);
CREATE TABLE video_tasks (
	id INTEGER NOT NULL, 
	video_id INTEGER NOT NULL, 
	title VARCHAR(500), 
	tags VARCHAR(500), 
	cover_url TEXT, 
	video_url TEXT, 
	guide_path VARCHAR(500), 
	output_path VARCHAR(500), 
	status VARCHAR(11), 
	message TEXT, 
	detail TEXT, 
	account_id INTEGER, 
	published_url VARCHAR(500), 
	started_at DATETIME, 
	completed_at DATETIME, 
	created_at DATETIME, category TEXT DEFAULT "", source_vid VARCHAR(200), target_platform VARCHAR(50), pool VARCHAR(100), 
	PRIMARY KEY (id), 
	FOREIGN KEY(video_id) REFERENCES videos (id), 
	FOREIGN KEY(account_id) REFERENCES "accounts_old" (id)
);
CREATE TABLE browsers (
	id INTEGER NOT NULL, 
	profile_id VARCHAR(100) NOT NULL, 
	seq INTEGER, 
	name VARCHAR(200), 
	status VARCHAR(20), 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	UNIQUE (profile_id)
);
CREATE TABLE accounts (
            id          INTEGER PRIMARY KEY AUTOINCREMENT,
            browser_id  INTEGER REFERENCES browsers(id),
            profile_id  VARCHAR(100),
            platform    VARCHAR(50) NOT NULL,
            name        VARCHAR(200),
            username    VARCHAR(100),
            tag         VARCHAR(100),
            group_id    VARCHAR(50),
            is_new      BOOLEAN DEFAULT 1,
            daily_limit INTEGER DEFAULT 3,
            status      VARCHAR(20) DEFAULT "active",
            created_at  DATETIME
        , disabled_reason VARCHAR(500), user_id INTEGER REFERENCES users(id));
CREATE TABLE publish_plans (
	id INTEGER NOT NULL, 
	name VARCHAR(200), 
	date DATE NOT NULL, 
	status VARCHAR(20), 
	created_at DATETIME, user_id INTEGER REFERENCES users(id), 
	PRIMARY KEY (id)
);
CREATE TABLE plan_items (
	id INTEGER NOT NULL, 
	plan_id INTEGER NOT NULL, 
	account_id INTEGER NOT NULL, 
	video_task_id INTEGER NOT NULL, 
	order_idx INTEGER, 
	publish_status VARCHAR(10), 
	published_url VARCHAR(500), 
	published_at DATETIME, 
	error_message TEXT, 
	created_at DATETIME, notified BOOLEAN DEFAULT 0, category TEXT DEFAULT "", platform VARCHAR(50) DEFAULT 'baijiahao', publish_mode VARCHAR(30) DEFAULT 'manual_confirm', view_count INTEGER, like_count INTEGER, comment_count INTEGER, stats_fetched_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(plan_id) REFERENCES publish_plans (id), 
	FOREIGN KEY(account_id) REFERENCES accounts (id), 
	FOREIGN KEY(video_task_id) REFERENCES video_tasks (id)
);
CREATE TABLE comment_tasks (
	id INTEGER NOT NULL, 
	plan_item_id INTEGER NOT NULL, 
	account_id INTEGER NOT NULL, 
	url VARCHAR(500) NOT NULL, 
	content TEXT, 
	status VARCHAR(10), 
	error_message TEXT, 
	commented_at DATETIME, 
	created_at DATETIME, category TEXT DEFAULT "", 
	PRIMARY KEY (id), 
	FOREIGN KEY(plan_item_id) REFERENCES plan_items (id), 
	FOREIGN KEY(account_id) REFERENCES accounts (id)
);
CREATE TABLE users (
	id INTEGER NOT NULL, 
	name VARCHAR(100) NOT NULL, 
	username VARCHAR(100), 
	role VARCHAR(50), 
	pool VARCHAR(100), 
	status VARCHAR(20), 
	wecom_id VARCHAR(100), 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	UNIQUE (username)
);
DELETE FROM sqlite_sequence;
CREATE INDEX ix_videos_source_vid ON videos(source_vid);
CREATE INDEX ix_video_tasks_status ON video_tasks (status);
CREATE INDEX ix_video_tasks_video_id ON video_tasks (video_id);
CREATE INDEX ix_accounts_browser_id ON accounts(browser_id);
CREATE INDEX ix_accounts_profile_id ON accounts(profile_id);
CREATE INDEX ix_publish_plans_date ON publish_plans (date);
CREATE INDEX ix_plan_items_video_task_id ON plan_items (video_task_id);
CREATE INDEX ix_plan_items_plan_id ON plan_items (plan_id);
CREATE INDEX ix_plan_items_publish_status ON plan_items (publish_status);
CREATE INDEX ix_plan_items_account_id ON plan_items (account_id);
CREATE INDEX ix_comment_tasks_status ON comment_tasks (status);
CREATE INDEX ix_comment_tasks_account_id ON comment_tasks (account_id);
CREATE INDEX ix_comment_tasks_plan_item_id ON comment_tasks (plan_item_id);
COMMIT;
